"""Ranked-choice tally: python3 tally.py INPUT_DIR OUTPUT_FILE (rules in /app/docs)."""
import csv
import io
import json
import os
import re
import sys


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    out = []
    for ch in s:
        if ch.isalpha() or ch.isdecimal():
            out.append(ch)
        else:
            out.append(" ")
    return " ".join("".join(out).split())


# ---------------------------------------------------------------- batches

def parse_revision(v):
    if isinstance(v, bool):
        raise ValueError("bad revision")
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        return int(v)
    return int(str(v).strip())


def read_csv_batch(path):
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        text = f.read()
    lines = text.split("\n")
    directives = {}
    pos = 0
    header_line = None
    while pos < len(lines):
        line = lines[pos].rstrip("\r")
        pos += 1
        s = line.strip()
        if not s:
            continue
        if s.startswith("#"):
            body = s[1:]
            if ":" in body:
                name, value = body.split(":", 1)
                directives[name.strip().lower()] = value.strip()
            continue
        header_line = pos - 1
        break
    records = []
    if header_line is None:
        return directives, records
    rest = "\n".join(lines[header_line:])
    reader = csv.reader(io.StringIO(rest, newline=""))
    header = None
    for row in reader:
        if header is None:
            header = [h.strip().lower() for h in row]
            cols = {}
            for i, h in enumerate(header):
                if h not in cols:
                    cols[h] = i
            ballot_i = cols.get("ballot")
            contest_i = cols.get("contest")
            rank_cols = []
            for h, i in cols.items():
                m = re.fullmatch(r"rank(\d+)", h)
                if m:
                    rank_cols.append((int(m.group(1)), i))
            continue
        if not row or all(not c.strip() for c in row):
            continue
        contest = row[contest_i] if contest_i is not None and contest_i < len(row) else ""
        ballot = row[ballot_i] if ballot_i is not None and ballot_i < len(row) else ""
        ranks = {}
        for n, i in rank_cols:
            if i < len(row):
                cell = row[i]
                marks = []
                for part in cell.split("|"):
                    p = part.strip()
                    if not p:
                        continue
                    if p[:3].lower() == "wi:":
                        marks.append(("w", p[3:]))
                    else:
                        marks.append(("c", p))
                if marks:
                    ranks[n] = marks
        records.append((ballot, contest.strip(), ranks))
    return directives, records


def read_jsonl_batch(path):
    directives = {}
    records = []
    first = True
    with open(path, "r", encoding="utf-8-sig") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            if first:
                first = False
                directives = {str(k).lower(): v for k, v in obj.items()}
                continue
            ranks = {}
            for m in obj.get("marks") or []:
                try:
                    n = int(m.get("rank"))
                except (TypeError, ValueError):
                    continue
                if m.get("candidate") is not None:
                    ranks.setdefault(n, []).append(("c", str(m["candidate"]).strip()))
                elif m.get("write_in") is not None:
                    ranks.setdefault(n, []).append(("w", str(m["write_in"])))
            records.append((obj.get("ballot"), str(obj.get("contest", "")).strip(), ranks))
    return directives, records


def load_counting_records(input_dir):
    cvr = os.path.join(input_dir, "cvr")
    best = {}  # batch id -> (revision, status, records)
    for name in sorted(os.listdir(cvr)):
        path = os.path.join(cvr, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            d, recs = read_csv_batch(path)
        elif name.endswith(".jsonl"):
            d, recs = read_jsonl_batch(path)
        else:
            continue
        batch = str(d.get("batch", "")).strip()
        rev = parse_revision(d.get("revision", 1))
        status = str(d.get("status", "final")).strip().lower()
        cur = best.get(batch)
        if cur is None or rev > cur[0]:
            best[batch] = (rev, status, recs)
    out = []
    for batch in sorted(best):
        rev, status, recs = best[batch]
        if status == "void":
            continue
        out.extend(recs)
    return out


# ---------------------------------------------------------------- ballots

def read_ballot(ranks, max_ranks, writein_map, withdrawn, known):
    """Return a tuple of rankings: ('S',), ('P',), ('C', id) or ('O',)."""
    result = []
    seen = set()
    for n in range(1, max_ranks + 1):
        marks = ranks.get(n, [])
        # a. write-ins
        cur = []
        for kind, val in marks:
            if kind == "w":
                cid = writein_map.get(norm_text(val))
                if cid is None:
                    continue
            else:
                cid = norm_id(val)
                if cid not in known:
                    continue
            if cid not in cur:
                cur.append(cid)
        if not cur:
            result.append(("S",))
            continue
        # b. withdrawn
        cur = [c for c in cur if c not in withdrawn]
        if not cur:
            result.append(("P",))
            continue
        # c. repeats
        before = cur
        cur = [c for c in before if c not in seen]
        seen.update(before)
        if not cur:
            result.append(("S",))
            continue
        # d.
        if len(cur) == 1:
            result.append(("C", cur[0]))
        else:
            result.append(("O",))
    return tuple(result)


def count_for(ballot, continuing):
    """Candidate the ballot counts for, or None when exhausted."""
    n = len(ballot)
    for i, r in enumerate(ballot):
        k = r[0]
        if k == "C":
            if r[1] in continuing:
                return r[1]
        elif k == "O":
            return None
        elif k == "S":
            if i + 1 < n and ballot[i + 1][0] == "S":
                return None
    return None


# ---------------------------------------------------------------- contest

def tally_contest(contest, records):
    max_ranks = int(contest.get("max_ranks", 0))
    cands = []  # (norm id, original id)
    withdrawn = set()
    for c in contest.get("candidates", []):
        cands.append((norm_id(c["id"]), c["id"]))
        if str(c.get("status", "active")).strip().lower() == "withdrawn":
            withdrawn.add(norm_id(c["id"]))
    writein_map = {}
    for w in contest.get("write_ins", []):
        cands.append((norm_id(w["id"]), w["id"]))
        for t in [w.get("name")] + list(w.get("aliases") or []):
            if t is None:
                continue
            nt = norm_text(t)
            if nt:
                writein_map.setdefault(nt, norm_id(w["id"]))
    orig = dict(cands)
    known = set(orig)
    lot = {}
    for i, cid in enumerate(contest.get("lot_order", [])):
        lot.setdefault(norm_id(cid), i)

    groups = {}
    for ranks in records:
        b = read_ballot(ranks, max_ranks, writein_map, withdrawn, known)
        groups[b] = groups.get(b, 0) + 1
    total = len(records)

    continuing = [c for c, _ in cands if c not in withdrawn]
    continuing_set = set(continuing)
    history = []  # list of dict norm id -> votes
    rounds = []
    winner = None
    while True:
        tallies = {c: 0 for c in continuing}
        active = 0
        for b, cnt in groups.items():
            c = count_for(b, continuing_set)
            if c is not None:
                tallies[c] += cnt
                active += cnt
        history.append(tallies)
        rnd = {
            "round": len(history),
            "tallies": {orig[c]: tallies[c] for c in continuing},
            "exhausted": total - active,
            "eliminated": [],
        }
        rounds.append(rnd)
        if active == 0:
            break
        top = [c for c in continuing if tallies[c] * 2 > active]
        if top:
            winner = orig[top[0]]
            break
        if len(continuing) == 1:
            winner = orig[continuing[0]]
            break
        zeros = [c for c in continuing if tallies[c] == 0]
        if zeros:
            elim = zeros
        else:
            low = min(tallies.values())
            tied = [c for c in continuing if tallies[c] == low]
            for h in range(len(history) - 2, -1, -1):
                if len(tied) <= 1:
                    break
                m = min(history[h][c] for c in tied)
                tied = [c for c in tied if history[h][c] == m]
            if len(tied) > 1:
                tied.sort(key=lambda c: lot.get(c, -1))
                tied = [tied[-1]]
            elim = tied
        rnd["eliminated"] = sorted(orig[c] for c in elim)
        es = set(elim)
        continuing = [c for c in continuing if c not in es]
        continuing_set = set(continuing)
    return {"contest": contest["id"], "ballots": total, "winner": winner, "rounds": rounds}


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    with open(os.path.join(input_dir, "election.json"), "r", encoding="utf-8-sig") as f:
        election = json.load(f)
    records = load_counting_records(input_dir)
    by_contest = {}
    for ballot, contest, ranks in records:
        by_contest.setdefault(contest, []).append(ranks)
    result = {"election": election["election"], "contests": []}
    for c in election["contests"]:
        result["contests"].append(tally_contest(c, by_contest.get(c["id"], [])))
    parent = os.path.dirname(os.path.abspath(output_file))
    os.makedirs(parent, exist_ok=True)
    with open(output_file, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)
        f.write("\n")


if __name__ == "__main__":
    main()
